// ---- generated by scripts/make_r2_tests.py of the probe: the readers
[[nodiscard]] std::string readPodSet(ApplicationSetterFixture& /*fixture*/,
                                     const RocketComponent& c)
{
    return listInOrder(
        {asText(angleMethodName(as<PodSet>(c).getAngleMethod())), num(c.getAngleOffset())});
}

