// The cases x303, x306 and x305 of the probe, through a setter of the test's own.
TEST(AnglePositionSetter, SetsTheMethodAndThenTheAngleInRadians)
{
    const AnglePositionSetter setter;
    EXPECT_EQ(applyByHand(setter, ComponentKind::PARALLEL_STAGE, "method=fixed", "30",
                          &readParallelStage),
              "FIXED, 0.5235987755982988");
    // What the saver writes for MIRROR_XY names no method: RELATIVE.
    EXPECT_EQ(applyByHand(setter, ComponentKind::PARALLEL_STAGE, "method=mirror_xy", "90",
                          &readParallelStage),
              "RELATIVE, 1.5707963267948966");
    EXPECT_EQ(applyByHand(setter, ComponentKind::PARALLEL_STAGE, "method=mirrorxy", "90",
                          &readParallelStage),
              "MIRROR_XY, 1.5707963267948966");
}

